return {api_version=1,id="EX1_365",name="Holy Wrath",text="Draw a card and deal damage equal to its Cost to a minion.",set="EXPERT1",type="spell",class="paladin",rarity="rare",spell_school="holy",cost=3,target_mode="required",targets=function(ctx)return ctx:minions()end,on_play=function(ctx,self,target)local p=ctx:controller(self);local deck=ctx:deck(p);local amount=0;if #deck>0 then amount=ctx:entity(deck[1]).cost end;ctx:draw(p,1);cardlib.effects.damage_ignoring_spell_damage(ctx, target,amount)end}
